#include <iostream>
#include <vector>
#include <stack>

using namespace std;

int main() {
    vector<int> nums;
    int x;
    while (cin >> x) {
        nums.push_back(x);
    }
    int n = nums.size();
    if (n == 0) return 0;
    vector<int> res(n, -1);
    stack<int> s;
    for (int i = 2 * n - 1; i >= 0; i--) {
        while (!s.empty() && nums[s.top()] <= nums[i % n]) {
            s.pop();
        }
        res[i % n] = s.empty() ? -1 : nums[s.top()];
        s.push(i % n);
    }
    for (int i = 0; i < n; i++) {
        cout << res[i] << (i == n - 1 ? "" : " ");
    }
    cout << endl;
    return 0;
}

